 final ScrollView source;final ImageView backdrop;final Handler handler=new Handler(Looper.getMainLooper());boolean queued;Bitmap prior;final PillSurface pill;final boolean blur,dark;final int base,accent;final android.view.ViewTreeObserver.OnScrollChangedListener scrollListener=this::queue;
 GlassDock(Context c,ScrollView source,View navigation,int previous,int selected){this(c,source,navigation,previous,selected,true,0xff17251f,0xffaacdb9,true);}
 GlassDock(Context c,ScrollView source,View navigation,int previous,int selected,boolean dark,int base,int accent,boolean blur){super(c);this.source=source;this.dark=dark;this.base=base;this.accent=accent;this.blur=blur;float d=c.getResources().getDisplayMetrics().density;GradientDrawable outline=new GradientDrawable();outline.setColor(base);outline.setCornerRadius(26*d);setBackground(outline);setClipToOutline(true);setElevation(10*d);backdrop=new ImageView(c);backdrop.setScaleType(ImageView.ScaleType.FIT_XY);backdrop.setAlpha(dark?.38f:.48f);addView(backdrop,new LayoutParams(-1,-1));pill=new PillSurface(d,previous,selected,accent,dark);navigation.setBackground(new LayerDrawable(new Drawable[]{new DockSurface(base,accent,dark,d),pill}));handler.post(()->pill.start());addView(navigation,new LayoutParams(-1,-2));if(blur)source.getViewTreeObserver().addOnScrollChangedListener(scrollListener);addOnLayoutChangeListener((v,a,b,z,e,f,g,h,i)->queue());}
 void queue(){if(queued||!blur)return;queued=true;handler.postDelayed(()->{queued=false;capture();},120);}
