 static final class PillSurface extends Drawable{final Paint p=new Paint(3);final float d;final int from,to,accent;final boolean dark;float value;android.animation.ValueAnimator animator;void stop(){if(animator!=null)animator.cancel();}PillSurface(float d,int from,int to){this(d,from,to,0xffaacdb9,true);}PillSurface(float d,int from,int to,int accent,boolean dark){this.d=d;this.from=from;this.to=to;this.accent=accent;this.dark=dark;value=from;}void start(){stop();android.animation.ValueAnimator a=android.animation.ValueAnimator.ofFloat(from,to);animator=a;a.setDuration(210);a.setInterpolator(new android.view.animation.DecelerateInterpolator());a.addUpdateListener(v->{value=(Float)v.getAnimatedValue();invalidateSelf();});a.start();}@Override public void draw(Canvas c){Rect b=getBounds();float pad=7*d,w=(b.width()-pad*2-54*d)/4f;RectF r=new RectF(pad+value*w+2*d,6*d,pad+(value+1)*w-2*d,b.height()-6*d);p.setStyle(Paint.Style.FILL);p.setColor((accent&0xffffff)|(dark?0x28000000:0x24000000));c.drawRoundRect(r,17*d,17*d,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(d);p.setColor(dark?0x548eb59e:0x88ffffff);c.drawRoundRect(r,17*d,17*d,p);}@Override public void setAlpha(int a){}@Override public void setColorFilter(ColorFilter f){}@Override public int getOpacity(){return PixelFormat.TRANSLUCENT;}}
